(*
 * Tank Monitor - a level in liters, its percentage of the capacity and a high level alarm.
 *)

PROGRAM TankMonitor

VAR_INPUT
    Setup AT %IX0.0 : BOOL;
    Fill AT %IX0.1 : BOOL;
    Drain AT %IX0.2 : BOOL;
END_VAR

VAR_OUTPUT
    Configured AT %QX0.0 : BOOL;
    HighAlarm AT %QX0.1 : BOOL;
END_VAR

VAR
    Level : DINT := 0;
    Capacity : DINT := 0;
    Scaled : DINT := 0;
    Percent : DINT := 0;
END_VAR

IF Setup THEN
    Capacity := 200;
END_IF;
IF Fill THEN
    Level := Level + 25;
END_IF;
IF Drain THEN
    Level := Level - 25;
END_IF;

Configured := Capacity <> 0;

IF Capacity <> 0 THEN
    Scaled := Level * 100;
    Percent := Scaled / Capacity;
END_IF;

HighAlarm := Percent >= 75;

END_PROGRAM

